package com.github.oinsio.gnomish.build

import org.gradle.testkit.runner.BuildResult
import org.gradle.testkit.runner.GradleRunner

import java.nio.file.Files
import java.nio.file.Path

/**
 * The miniature java-library project the api-compatibility gate is exercised on
 * (FR1, design D3 of add-functional-api-gate-test).
 *
 * Written inline rather than committed as a resource: the fixture is a handful
 * of lines, and its baseline jars are GENERATED by the gate's own
 * {@code updateApiCompatibilityBaseline} task instead of being opaque binaries
 * that rot against the toolchain.
 *
 * Hermetic (NFR-R1): the convention plugins reach the build through TestKit's
 * plugin classpath, and every scenario runs {@code --offline} against the outer
 * build's Gradle user home, so nothing is fetched while a scenario runs. The
 * single declared repository exists only so japicmp's worker can resolve its own
 * hardcoded JAXB/Guava coordinates from that warm cache — see the note in
 * `build-logic/build.gradle`.
 */
final class MiniApiProject {

    /** The public surface the scenarios start from; `answer()` is the member removed to break compatibility. */
    static final String API_WITH_ANSWER = """\
package com.example.mini;

public class MiniApi {
    public String greet(String name) {
        return "hello " + name;
    }

    public int answer() {
        return 42;
    }
}
"""

    /** The same surface with `answer()` removed — a binary-incompatible method removal (FR2). */
    static final String API_WITHOUT_ANSWER = """\
package com.example.mini;

public class MiniApi {
    public String greet(String name) {
        return "hello " + name;
    }
}
"""

    /** The original surface plus a new public method — a compatible addition (FR3). */
    static final String API_WITH_ADDITION = """\
package com.example.mini;

public class MiniApi {
    public String greet(String name) {
        return "hello " + name;
    }

    public int answer() {
        return 42;
    }

    public String farewell(String name) {
        return "bye " + name;
    }
}
"""

    private final Path projectDir

    MiniApiProject(Path projectDir) {
        this.projectDir = projectDir
    }

    /** Writes settings, build script and the initial api source. */
    void write() {
        writeFile('settings.gradle', "rootProject.name = 'mini-api'\n")
        writeFile('build.gradle', '''\
plugins {
    id 'api-compatibility-gate-conventions'
}

// japicmp resolves its worker's JAXB/Guava runtime from HERE, at execution
// time, from coordinates hardcoded in the plugin. Every scenario runs
// `--offline` against the outer build's dependency cache (NFR-R1), so this
// declaration lets those cached modules resolve without any network access.
repositories {
    mavenCentral()
}

group = 'com.example'
version = '1.0.0'
''')
        writeApi(API_WITH_ANSWER)
    }

    /** Replaces the single public api source file. */
    void writeApi(String source) {
        writeFile('src/main/java/com/example/mini/MiniApi.java', source)
    }

    /** Empties the generated baseline directory without removing it (FR4). */
    void emptyBaseline() {
        baselineJars().each { Files.delete(it) }
    }

    List<Path> baselineJars() {
        Path dir = projectDir.resolve('compat-baseline')
        if (!Files.isDirectory(dir)) {
            return []
        }
        Files.list(dir).withCloseable { jars ->
            jars.filter { it.toString().endsWith('.jar') }.toList()
        }
    }

    /** The japicmp text report, or a placeholder — surfaced in assertion messages (NFR-O1). */
    String japicmpReport() {
        Path report = projectDir.resolve('build/reports/japicmp/api-compatibility.txt')
        Files.exists(report) ? report.text : "(no japicmp report at ${report})"
    }

    /** Deletes the gate's report outputs so a following run is SUCCESS rather than UP-TO-DATE (FR5). */
    void invalidateGateOutputs() {
        projectDir.resolve('build/reports/japicmp').toFile().deleteDir()
    }

    BuildResult build(String... tasks) {
        runner(tasks).build()
    }

    BuildResult buildAndFail(String... tasks) {
        runner(tasks).buildAndFail()
    }

    private GradleRunner runner(String... tasks) {
        GradleRunner.create()
                .withProjectDir(projectDir.toFile())
                .withPluginClasspath()
                .withArguments([*tasks, '--offline', '--stacktrace', '-g', gradleUserHome()])
                .forwardOutput()
    }

    /** The outer build's Gradle user home — shared so `--offline` resolves from a warm cache (NFR-R1). */
    private static String gradleUserHome() {
        String home = System.getProperty('gnomish.gradleUserHome')
        assert home != null: 'functionalTest must pass -Dgnomish.gradleUserHome (see build-logic/build.gradle)'
        home
    }

    private void writeFile(String relativePath, String content) {
        Path target = projectDir.resolve(relativePath)
        Files.createDirectories(target.parent)
        target.text = content
    }
}
